            ) {
                shouldDelete = true;
            }

            if (shouldDelete) {
                editorContentRootDiv?.removeChild(current);
            }

            current = next;
        }

        if (args.returnType === 'html') {
            return editorContentRootDiv.innerHTML;
        }

        return editorContentRootDiv.innerText;
    }

    return '';
};

